from pathlib import Path
import json
base=Path.home()/'.local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4'
task='A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2'
p=base/'model_results'/(task+'.json')
o=json.loads(p.read_text(encoding='utf-8'))
def compact(v,depth=0):
    if depth>=3:
        return type(v).__name__
    if isinstance(v,dict):
        return {k:compact(v[k],depth+1) for k in list(v)[:40]}
    if isinstance(v,list):
        return [compact(x,depth+1) for x in v[:8]]
    if isinstance(v,str):
        return v[:4000]
    return v
out={'top_keys':list(o.keys()),'compact':compact(o)}
print('ERROR_CLASS=R4P2_PREBUILD_RAW_SCHEMA',flush=True)
print('ERROR='+json.dumps(out,separators=(',',':'),sort_keys=True),flush=True)
raise SystemExit(1)
